-- Vegetable planner tables. They hang off the same farms as the flowers,
-- with their own beds. shared_bed_id is reserved so a later phase can point
-- a veg bed and a flower bed at one shared bed. It stays null for now.

create table public.veg_vegetables (
  id text primary key,
  name text not null,
  family text not null,
  category text not null,
  frost_tolerance text not null,
  min_soil_temp_c double precision,
  color text not null,
  notes text not null default ''
);

create table public.veg_frost_locations (
  id text primary key,
  country text not null,
  region text not null,
  name text not null,
  latitude double precision not null,
  longitude double precision not null,
  last_spring_frost text not null,
  first_autumn_frost text not null,
  source_name text not null,
  source_url text not null
);

create table public.veg_crops (
  id text primary key,
  farm_id uuid references public.farms (id) on delete cascade,
  name text not null,
  cultivar text not null,
  category text not null,
  planting_method text not null,
  days_to_maturity integer not null,
  days_in_nursery integer not null,
  harvest_window_days integer not null,
  rows_per_bed integer not null,
  in_row_spacing_in double precision not null,
  yield_per_100_bed_feet double precision not null,
  yield_unit text not null,
  color text not null,
  notes text not null default '',
  vegetable_id text,
  family text,
  frost_tolerance text,
  min_soil_temp_c double precision,
  supplier text,
  source_name text,
  source_url text,
  between_row_cm double precision,
  germination_temp_min double precision,
  germination_temp_max double precision,
  germination_days_min integer,
  germination_days_max integer,
  sow_indoors_start integer,
  sow_indoors_end integer,
  sow_outdoors_start integer,
  sow_outdoors_end integer,
  transplant_start integer,
  transplant_end integer,
  hardiness_notes text,
  yield_is_estimate boolean not null default true,
  dtm_is_typical boolean not null default false,
  user_created boolean not null default false,
  rotation_family text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.veg_crop_overrides (
  farm_id uuid not null references public.farms (id) on delete cascade,
  crop_id text not null references public.veg_crops (id) on delete cascade,
  rotation_family text not null,
  primary key (farm_id, crop_id)
);

create table public.veg_companions (
  id text primary key,
  farm_id uuid references public.farms (id) on delete cascade,
  crop_name text not null,
  other_name text not null,
  kind text not null check (kind in ('good', 'bad')),
  reason text not null,
  user_created boolean not null default false
);

create table public.veg_farm_settings (
  farm_id uuid primary key references public.farms (id) on delete cascade,
  country text not null default 'GB',
  location_label text not null default '',
  frost_location_id text references public.veg_frost_locations (id),
  latitude double precision,
  longitude double precision,
  manual_last_spring_frost text,
  manual_first_autumn_frost text,
  use_manual_frost boolean not null default false,
  rotation_years integer not null default 3
);

create table public.veg_farm_areas (
  id text primary key,
  farm_id uuid not null references public.farms (id) on delete cascade,
  name text not null,
  outline_json text not null,
  area_m2 double precision not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.veg_blocks (
  id text primary key,
  farm_id uuid not null references public.farms (id) on delete cascade,
  name text not null,
  type text not null,
  bed_length double precision not null,
  bed_width double precision not null,
  path_width double precision not null,
  unit text not null,
  notes text not null default '',
  sort_order integer not null default 0,
  farm_area_id text references public.veg_farm_areas (id) on delete set null,
  center_lat double precision,
  center_lng double precision,
  rotation_deg double precision,
  span_length_m double precision,
  span_width_m double precision,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.veg_beds (
  id text primary key,
  farm_id uuid not null references public.farms (id) on delete cascade,
  block_id text not null references public.veg_blocks (id) on delete cascade,
  label text not null,
  position integer not null,
  length double precision not null,
  width double precision not null,
  -- Reserved for phase 7. Null while flowers and vegetables keep separate beds.
  shared_bed_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.veg_plantings (
  id text primary key,
  farm_id uuid not null references public.farms (id) on delete cascade,
  crop_id text not null references public.veg_crops (id),
  season_year integer not null,
  planting_method text not null,
  date_mode text not null,
  anchor_date text not null,
  nursery_start_date text,
  field_planting_date text not null,
  first_harvest_date text not null,
  last_harvest_date text not null,
  bed_feet double precision not null default 0,
  predicted_yield double precision not null default 0,
  yield_unit text not null,
  succession_group_id text,
  succession_index integer,
  succession_count integer,
  parent_planting_id text,
  notes text not null default '',
  beds_needed integer,
  bed_length_m double precision,
  rows_per_bed integer,
  in_row_spacing_cm double precision,
  expected_revenue double precision,
  used_days_to_maturity integer,
  used_days_in_nursery integer,
  used_harvest_window_days integer,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.veg_planting_beds (
  farm_id uuid not null references public.farms (id) on delete cascade,
  planting_id text not null references public.veg_plantings (id) on delete cascade,
  bed_id text not null references public.veg_beds (id) on delete restrict,
  primary key (planting_id, bed_id)
);

create table public.veg_custom_task_types (
  id text primary key,
  farm_id uuid not null references public.farms (id) on delete cascade,
  name text not null,
  created_at timestamptz not null default now()
);

create table public.veg_tasks (
  id text primary key,
  farm_id uuid not null references public.farms (id) on delete cascade,
  planting_id text references public.veg_plantings (id) on delete cascade,
  task_key text,
  title text not null,
  task_type text not null,
  due_date text not null,
  status text not null,
  notes text not null default '',
  minutes integer,
  repeat_every_days integer,
  repeat_until text,
  manually_edited boolean not null default false,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.veg_vegetables enable row level security;
alter table public.veg_frost_locations enable row level security;
alter table public.veg_crops enable row level security;
alter table public.veg_crop_overrides enable row level security;
alter table public.veg_companions enable row level security;
alter table public.veg_farm_settings enable row level security;
alter table public.veg_farm_areas enable row level security;
alter table public.veg_blocks enable row level security;
alter table public.veg_beds enable row level security;
alter table public.veg_plantings enable row level security;
alter table public.veg_planting_beds enable row level security;
alter table public.veg_custom_task_types enable row level security;
alter table public.veg_tasks enable row level security;

create policy "read veg vegetables" on public.veg_vegetables for select to authenticated using (public.is_approved());
create policy "read veg frost" on public.veg_frost_locations for select to authenticated using (public.is_approved());

create policy "read veg crops" on public.veg_crops for select to authenticated
using (public.is_approved() and (farm_id is null or public.owns_farm(farm_id)));
create policy "insert own veg crops" on public.veg_crops for insert to authenticated
with check (farm_id is not null and public.owns_farm(farm_id) and user_created);
create policy "update own veg crops" on public.veg_crops for update to authenticated
using (farm_id is not null and public.owns_farm(farm_id))
with check (farm_id is not null and public.owns_farm(farm_id));
create policy "delete own veg crops" on public.veg_crops for delete to authenticated
using (farm_id is not null and public.owns_farm(farm_id) and user_created);

create policy "own veg overrides" on public.veg_crop_overrides for all to authenticated
using (public.owns_farm(farm_id)) with check (public.owns_farm(farm_id));

create policy "read veg companions" on public.veg_companions for select to authenticated
using (public.is_approved() and (farm_id is null or public.owns_farm(farm_id)));
create policy "write own veg companions" on public.veg_companions for insert to authenticated
with check (farm_id is not null and public.owns_farm(farm_id));
create policy "delete own veg companions" on public.veg_companions for delete to authenticated
using (farm_id is not null and public.owns_farm(farm_id));

create policy "own veg settings" on public.veg_farm_settings for all to authenticated
using (public.owns_farm(farm_id)) with check (public.owns_farm(farm_id));
create policy "own veg areas" on public.veg_farm_areas for all to authenticated
using (public.owns_farm(farm_id)) with check (public.owns_farm(farm_id));
create policy "own veg blocks" on public.veg_blocks for all to authenticated
using (public.owns_farm(farm_id)) with check (public.owns_farm(farm_id));
create policy "own veg beds" on public.veg_beds for all to authenticated
using (public.owns_farm(farm_id)) with check (public.owns_farm(farm_id));
create policy "own veg plantings" on public.veg_plantings for all to authenticated
using (public.owns_farm(farm_id)) with check (public.owns_farm(farm_id));
create policy "own veg planting beds" on public.veg_planting_beds for all to authenticated
using (public.owns_farm(farm_id)) with check (public.owns_farm(farm_id));
create policy "own veg task types" on public.veg_custom_task_types for all to authenticated
using (public.owns_farm(farm_id)) with check (public.owns_farm(farm_id));
create policy "own veg tasks" on public.veg_tasks for all to authenticated
using (public.owns_farm(farm_id)) with check (public.owns_farm(farm_id));

grant select on public.veg_vegetables, public.veg_frost_locations, public.veg_crops, public.veg_companions to authenticated;
grant select, insert, update, delete on public.veg_crops, public.veg_companions, public.veg_crop_overrides,
  public.veg_farm_settings, public.veg_farm_areas, public.veg_blocks, public.veg_beds, public.veg_plantings,
  public.veg_planting_beds, public.veg_custom_task_types, public.veg_tasks to authenticated;

